import { useEffect,useMemo,useState } from "react"
import type { RouteConfig } from "@mercurjs/dashboard-sdk"
import "../../spike/vendor-spike.css"
declare const __BACKEND_URL__:string
export const config:RouteConfig={label:"منتجاتي",rank:18}

type P={id:string;title:string;description?:string;status?:string;thumbnail?:string;variants?:any[]}
type Office={id:string;name:string;city?:string;governorate?:string}
type Revision={id:string;product_id:string;status:string;rejection_reason?:string;changes?:Record<string,any>;created_at?:string}
type Assignment={product_id:string;delivery_office_id:string}
const api=async(path:string,init?:RequestInit)=>{const r=await fetch(`${__BACKEND_URL__}${path}`,{credentials:'include',...init,headers:{...(init?.body?{'content-type':'application/json'}:{}),...(init?.headers||{})}});const t=await r.text();let d:any={};try{d=t?JSON.parse(t):{}}catch{}if(!r.ok)throw new Error(d.message||t||`HTTP ${r.status}`);return d}
const statusText=(v?:string)=>{const s=String(v||'').toLowerCase();if(s==='pending'||s==='proposed')return 'بانتظار المراجعة';if(s==='published'||s==='approved')return 'منشور';if(s==='rejected')return 'مرفوض';if(s==='draft')return 'مسودة';return v||'—'}
const revisionText=(v?:string)=>{const s=String(v||'').toLowerCase();if(s==='pending')return 'تعديل بانتظار الموافقة';if(s==='approved')return 'تمت الموافقة';if(s==='rejected')return 'تم رفض التعديل';return ''}
export default function MyProducts(){
 const [products,setProducts]=useState<P[]>([]),[offices,setOffices]=useState<Office[]>([]),[assignments,setAssignments]=useState<Assignment[]>([]),[revisions,setRevisions]=useState<Revision[]>([]),[editing,setEditing]=useState<any>(null),[msg,setMsg]=useState(''),[query,setQuery]=useState(''),[filter,setFilter]=useState('all'),[loading,setLoading]=useState(true)
 const load=async()=>{setLoading(true);try{const [p,o,r]=await Promise.all([api('/vendor/products?limit=100&fields=id,title,description,status,thumbnail,*variants'),api('/vendor/spike/product-delivery'),api('/vendor/spike/product-revisions')]);setProducts(p.products||[]);setOffices(o.offices||[]);setAssignments(o.assignments||[]);setRevisions(r.revisions||[])}finally{setLoading(false)}}
 useEffect(()=>{load().catch(e=>setMsg(e.message))},[])
 const officeMap=useMemo(()=>new Map(offices.map(o=>[o.id,o])),[offices])
 const assignmentMap=useMemo(()=>new Map(assignments.map(a=>[a.product_id,a.delivery_office_id])),[assignments])
 const latestRevision=useMemo(()=>{const m=new Map<string,Revision>();for(const r of revisions){if(!m.has(r.product_id))m.set(r.product_id,r)}return m},[revisions])
 const visible=products.filter(p=>{const q=query.trim().toLowerCase();const matches=!q||p.title.toLowerCase().includes(q)||String(p.variants?.[0]?.sku||'').toLowerCase().includes(q);if(!matches)return false;if(filter==='all')return true;const rev=latestRevision.get(p.id);if(filter==='pending')return String(rev?.status||p.status||'').toLowerCase().includes('pending')||p.status==='proposed';if(filter==='published')return ['published','approved'].includes(String(p.status||'').toLowerCase());if(filter==='rejected')return String(rev?.status||p.status||'').toLowerCase()==='rejected';return true})
 const start=(p:P)=>{const aid=assignmentMap.get(p.id)||'';setEditing({product:p,title:p.title,description:p.description||'',price:'',currency:'SAR',delivery_office_id:aid})}
 const remove=async(p:P)=>{if(!confirm(`هل تريد حذف ${p.title}؟`))return;try{await api(`/vendor/spike/products/${p.id}`,{method:'DELETE'});setMsg('تم حذف المنتج');await load()}catch(e:any){setMsg(e.message||'تعذر حذف المنتج')}}
 const save=async()=>{const p=editing.product;const offerId=p.variants?.find((v:any)=>v.offers?.length)?.offers?.[0]?.id||p.variants?.find((v:any)=>v.offer_id)?.offer_id||null;const changes:any={title:editing.title,description:editing.description,delivery_office_id:editing.delivery_office_id};if(editing.price)changes.price=Number(editing.price),changes.currency=editing.currency;await api('/vendor/spike/product-revisions',{method:'POST',body:JSON.stringify({product_id:p.id,offer_id:offerId,product_title:p.title,changes})});setMsg('تم إرسال التعديل للإدارة. سيظهر لك إشعار بعد الموافقة أو الرفض.');setEditing(null);await load()}
 return <div className="spike-vendor-page spike-products-page" dir="rtl">
  <div className="spike-vendor-card spike-page-header"><div><h1>منتجاتي</h1><p>إدارة منتجات متجرك من مكان واحد: الحالة، المخزون، مكتب التوصيل والتعديلات.</p></div></div>
  {msg&&<div className="spike-vendor-note">{msg}</div>}
  <div className="spike-vendor-card spike-products-toolbar"><div className="spike-search"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="ابحث باسم المنتج أو SKU"/></div><div className="spike-filter-tabs">{[['all','الكل'],['published','منشور'],['pending','بانتظار المراجعة'],['rejected','مرفوض']].map(([k,l])=><button key={k} className={filter===k?'active':''} onClick={()=>setFilter(k)}>{l}</button>)}</div></div>
  <div className="spike-vendor-card spike-table-card">{loading?<div className="spike-empty">جاري تحميل المنتجات...</div>:visible.length?<div className="spike-responsive-table"><table className="spike-vendor-table"><thead><tr><th>المنتج</th><th>الحالة</th><th>SKU</th><th>المخزون</th><th>مكتب التوصيل</th><th>آخر تعديل</th><th></th></tr></thead><tbody>{visible.map(p=>{const rev=latestRevision.get(p.id),office=officeMap.get(assignmentMap.get(p.id)||'');const stock=p.variants?.[0]?.inventory_quantity??p.variants?.[0]?.inventoryQuantity??'—';return <tr key={p.id}><td><div className="spike-product-cell">{p.thumbnail?<img src={p.thumbnail} alt=""/>:<div className="spike-product-thumb">SP</div>}<div><b>{p.title}</b><small>{p.description||'بدون وصف'}</small></div></div></td><td><span className={`spike-status-pill ${String(p.status||'').toLowerCase()}`}>{statusText(p.status)}</span></td><td><code>{p.variants?.[0]?.sku||'—'}</code></td><td>{stock}</td><td>{office?<span className="spike-office-chip">{office.name}</span>:<span className="spike-warning-text">غير محدد</span>}</td><td>{rev?<div className="spike-revision-state"><span className={`spike-status-pill ${rev.status}`}>{revisionText(rev.status)}</span>{rev.status==='rejected'&&rev.rejection_reason?<small>{rev.rejection_reason}</small>:null}</div>:<span className="spike-muted-text">لا يوجد</span>}</td><td><button className="spike-table-action" onClick={()=>start(p)}>تعديل</button> <button className="spike-table-action" onClick={()=>remove(p)}>حذف</button></td></tr>})}</tbody></table></div>:<div className="spike-empty"><b>لا توجد منتجات مطابقة</b><span>غيّر الفلتر أو البحث.</span></div>}</div>
  {editing&&<div className="spike-modal-backdrop" onMouseDown={()=>setEditing(null)}><div className="spike-edit-modal" onMouseDown={e=>e.stopPropagation()}><div className="spike-modal-head"><div><h2>تعديل المنتج</h2><p>{editing.product.title}</p></div><button onClick={()=>setEditing(null)}>×</button></div><div className="spike-vendor-grid"><label>اسم المنتج<input value={editing.title} onChange={e=>setEditing({...editing,title:e.target.value})}/></label><label className="span-2">الوصف<textarea rows={4} value={editing.description} onChange={e=>setEditing({...editing,description:e.target.value})}/></label><label>السعر الجديد<input type="number" min="0" value={editing.price} onChange={e=>setEditing({...editing,price:e.target.value})} placeholder="اتركه فارغًا بدون تغيير"/></label><label>مكتب التوصيل<select value={editing.delivery_office_id} onChange={e=>setEditing({...editing,delivery_office_id:e.target.value})}><option value="">اختر المكتب</option>{offices.map(o=><option key={o.id} value={o.id}>{o.name}{o.city?` - ${o.city}`:''}</option>)}</select></label></div><div className="spike-review-hint">أي تعديل يتم إرساله للإدارة للمراجعة قبل اعتماده.</div><div className="spike-vendor-actions"><button className="spike-primary-button" onClick={save}>إرسال للموافقة</button><button className="spike-secondary-button" onClick={()=>setEditing(null)}>إلغاء</button></div></div></div>}
 </div>
}
